import { MakeLogicType, actions, kea, path, reducers } from 'kea'

/** Whether each group is collapsed, keyed by dashboard id and then by group key. */
export type TileGroupChoices = Record<string, Record<string, boolean>>

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface dashboardTileGroupChoicesLogicValues {
    tileGroupChoices: TileGroupChoices
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface dashboardTileGroupChoicesLogicActions {
    setTileGroupCollapsed: (
        dashboardId: number,
        groupKey: string,
        collapsed: boolean
    ) => {
        collapsed: boolean
        dashboardId: number
        groupKey: string
    }
}

export type dashboardTileGroupChoicesLogicType = MakeLogicType<
    dashboardTileGroupChoicesLogicValues,
    dashboardTileGroupChoicesLogicActions
>

// One persisted map for every dashboard in this browser, so a viewer's open or closed groups outlive the page.
export const dashboardTileGroupChoicesLogic = kea<dashboardTileGroupChoicesLogicType>([
    path(['products', 'dashboards', 'frontend', 'dashboardTileGroupChoicesLogic']),
    actions({
        setTileGroupCollapsed: (dashboardId: number, groupKey: string, collapsed: boolean) => ({
            dashboardId,
            groupKey,
            collapsed,
        }),
    }),
    reducers({
        tileGroupChoices: [
            {} as TileGroupChoices,
            { persist: true },
            {
                setTileGroupCollapsed: (state, { dashboardId, groupKey, collapsed }) => ({
                    ...state,
                    [dashboardId]: { ...state[dashboardId], [groupKey]: collapsed },
                }),
            },
        ],
    }),
])
